"""Golden raster is generated by independent Python integer image operations."""
from pathlib import Path
import subprocess,json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'build/advanced_sim'
# Explicit 5-bit scanlines form the independent expected bitmap specification.
FONT={
'0':[14,17,19,21,25,17,14],'1':[4,12,4,4,4,4,14],
'2':[14,17,1,2,4,8,31],'3':[30,1,1,6,1,1,30],
'4':[2,6,10,18,31,2,2],'5':[31,16,30,1,1,17,14],
'6':[6,8,16,30,17,17,14],'7':[31,1,2,4,8,8,8],
'8':[14,17,17,14,17,17,14],'9':[14,17,17,15,1,2,12],
'A':[14,17,17,31,17,17,17],'B':[30,17,17,30,17,17,30],
'C':[14,17,16,16,16,17,14],'D':[30,17,17,17,17,17,30],
'E':[31,16,16,30,16,16,31],'F':[31,16,16,30,16,16,16],
'G':[14,17,16,23,17,17,15],'H':[17,17,17,31,17,17,17],
'I':[14,4,4,4,4,4,14],'L':[16,16,16,16,16,16,31],
'N':[17,25,21,19,17,17,17],'O':[14,17,17,17,17,17,14],
'M':[17,27,21,21,17,17,17],'P':[30,17,17,30,16,16,16],
'R':[30,17,17,30,20,18,17],'S':[15,16,16,14,1,1,30],
'T':[31,4,4,4,4,4,4],'U':[17,17,17,17,17,17,14],
'Y':[17,17,10,4,4,4,4],':':[0,4,4,0,4,4,0],
'+':[0,4,4,31,4,4,0],'%':[25,25,2,4,8,19,19],'/':[1,1,2,4,8,16,16]}

def ink(text,x,y):
    c,col=divmod(x,8)
    return 0<=c<len(text) and 0<=y<7 and col<5 and bool(FONT.get(text[c],[0]*7)[y]&(1<<(4-col)))
def half(rgb,color):return tuple((a+b)//2 for a,b in zip(rgb,color))
def frame(style,n):
    for y in range(480):
        for x in range(640):
            rgb=((x*19+y*5)&255,(x*3+y*17)&255,(x*7+y*11)&255)
            if style==2:rgb=tuple(min(255,v+32)//2 for v in rgb)
            if style==4:rgb=tuple(min(255,v+64)*12//16 for v in rgb)
            if style==5 and x>=320:rgb=(0,0,0)
            if style==6:rgb=tuple(max(0,min(255,(v-128)*2+128-32)) for v in rgb)
            if style==7:rgb=tuple(max(0,min(255,(v-128)//2+128+32)) for v in rgb)
            if style==8:rgb=tuple(max(0,min(255,(v-128)+(v-128)//2+128+64)) for v in rgb)
            if style in (3,4) and 64<=x<576 and 288<=y<417:
                rgb=half(rgb,(0,32,32))
                if y==352:rgb=(48,80,80)
                if style==4 and n==1:
                    if y==344:rgb=(32,255,96)
                    if y>=408 and x<128:rgb=(255,176,32)
            if (style==1 and n==0) or style==4:
                if 8<=x<304 and 8<=y<56:rgb=half(rgb,(16,24,40))
                if 448<=y<472:rgb=half(rgb,(0,32,64))
                params='B+64 C100% CUT  SOUND OFF' if style==4 else 'B+00 C100% CUT  SOUND OFF'
                if (ink('TIME 00:00',x-16,y-12) or ink(params,x-16,y-28)
                    or ink('CACHE 4/4 IMG 01/06',x-16,y-44)
                    or ink('EG4S20 HDMI MULTIMEDIA PLAYER    ',x+n,y-456)):
                    rgb=(255,255,255)
            yield '%02x%02x%02x\n'%rgb
def main():
    OUT.mkdir(parents=True,exist_ok=True);exe=OUT/'video_golden.vvp'
    sources=['src/video/advanced_video.v','src/control/video_controls.v','src/audio/audio_scope.v','src/video/osd_font.v']
    subprocess.run(['iverilog','-g2012','-s','tb_video_golden','-o',str(exe),
        *sources,'src/video/video_rgb_to_axis_640x480.v','test/tb_video_golden.sv'],cwd=ROOT,check=True)
    for style in range(9):
        p=OUT/f'video_{style}.rgb'
        with p.open('w') as f:
            for n in range(2):f.writelines(frame(style,n))
        r=subprocess.run(['vvp',str(exe),f'+GOLDEN={p.as_posix()}',f'+STYLE={style}'],cwd=ROOT,capture_output=True,text=True,timeout=120)
        (OUT/f'video_{style}.log').write_text(r.stdout+r.stderr)
        assert r.returncode==0,r.stdout+r.stderr
        print(r.stdout.strip())
    print('PASS independent golden comparison: 18 full frames / 5529600 pixels')
if __name__=='__main__':main()
